// Fire account balance property event
import java.beans.*;public class Q07 {public static class AccountBean {private double balance=500;private final PropertyChangeSupport pcs=new PropertyChangeSupport(this);public AccountBean(){}public double getBalance(){return balance;}public void setBalance(double value){double old=balance;balance=value;pcs.firePropertyChange("balance",old,value);}public void addPropertyChangeListener(PropertyChangeListener l){pcs.addPropertyChangeListener(l);}}public static void main(String[] args){AccountBean a=new AccountBean();a.addPropertyChangeListener(evt->System.out.println("Event: "+evt.getOldValue()+" -> "+evt.getNewValue()));a.setBalance(650);a.setBalance(800);}}
